def valid(text):
    """题面只给格式、未给数据范围：第一行两个整数 N,D；第二行 2N 个整数。
    这里额外只要求 N ≥ 1、D ≥ 0、身高为非负整数（身高差/身高的自然含义）。"""
    if not text.endswith('\n'):
        return False
    lines = text[:-1].split('\n')
    if len(lines) != 2 or not _re.fullmatch(r'[1-9]\d* (0|[1-9]\d*)', lines[0]):
        return False
    n = int(lines[0].split()[0])
    toks = lines[1].split(' ')
    return len(toks) == 2 * n and all(_re.fullmatch(r'0|[1-9]\d*', t) for t in toks)

def valid(text):
    """题面契约：第一行 n（1<=n<=10^6）；第二行 n 个升序非负整数，每个不超过 n。"""
    if not text.endswith("\n"):
        return False
    lines = text[:-1].split("\n")
    if len(lines) != 2:
        return False
    head = lines[0].split(" ")
    if len(head) != 1 or not head[0].isdigit():
        return False
    n = int(head[0])
    if not 1 <= n <= 10**6 or str(n) != head[0]:
        return False
    toks = lines[1].split(" ")
    if len(toks) != n or any(not t.isdigit() or str(int(t)) != t for t in toks):
        return False
    a = list(map(int, toks))
    return all(0 <= x <= n for x in a) and all(a[i] <= a[i + 1] for i in range(n - 1))

def valid(text):
    """题面契约：n,t；n-1 条边构成以 t 为根的树（1<=u,v<=n，u!=v）；m 行 p q v1 v2，
    1<=n,m<=2e5，1<=t,p,q<=n，1<=v1,v2<=1e9，且 p 到 q 的距离 L 满足 L mod (v1+v2)=0。"""
    if not text.endswith("\n"):
        return False
    lines = text[:-1].split("\n")
    def ints(line, k):
        toks = line.split(" ")
        if len(toks) != k or any(not x.isdigit() or str(int(x)) != x for x in toks):
            return None
        return list(map(int, toks))
    first = ints(lines[0], 2)
    if first is None:
        return False
    n, t = first
    if not (1 <= n <= 200000 and 1 <= t <= n) or len(lines) < n + 1:
        return False
    adj = [[] for _ in range(n + 1)]
    for line in lines[1:n]:
        e = ints(line, 2)
        if e is None:
            return False
        u, v = e
        if not (1 <= u <= n and 1 <= v <= n and u != v):
            return False
        adj[u].append(v); adj[v].append(u)
    # 连通且 n-1 条边 => 树
    par = [0] * (n + 1); dep = [-1] * (n + 1); dep[t] = 0; order = [t]
    for u in order:
        for v in adj[u]:
            if dep[v] < 0:
                dep[v] = dep[u] + 1; par[v] = u; order.append(v)
    if len(order) != n:
        return False
    mline = ints(lines[n], 1)
    if mline is None:
        return False
    m = mline[0]
    if not 1 <= m <= 200000 or len(lines) != n + 1 + m:
        return False
    LOG = max(1, n.bit_length())
    up = [par[:]]
    for j in range(1, LOG):
        prv = up[-1]; up.append([prv[prv[i]] for i in range(n + 1)])
    def lca(a, b):
        if dep[a] < dep[b]:
            a, b = b, a
        d = dep[a] - dep[b]; j = 0
        while d:
            if d & 1:
                a = up[j][a]
            d >>= 1; j += 1
        if a == b:
            return a
        for j in range(LOG - 1, -1, -1):
            if up[j][a] != up[j][b]:
                a = up[j][a]; b = up[j][b]
        return par[a]
    for line in lines[n + 1:]:
        qv = ints(line, 4)
        if qv is None:
            return False
        p, q, v1, v2 = qv
        if not (1 <= p <= n and 1 <= q <= n and 1 <= v1 <= 10**9 and 1 <= v2 <= 10**9):
            return False
        L = dep[p] + dep[q] - 2 * dep[lca(p, q)]
        if L % (v1 + v2):
            return False
    return True

def valid(text):
    """题面约束：第一行 n（1<=n<=5*10^5）；第二行 n 个两两不同的整数 xi（1<=xi<=10^9）。"""
    lines = text.split('\n')
    if lines and lines[-1] == '':
        lines.pop()
    if len(lines) != 2 or not _INT.match(lines[0].strip()):
        return False
