 if output.exists():result=json.loads(output.read_text())
 else:result={'batch':batch,'baseline':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'started_at':now(),'entries':[],'scope':'只读复核与公开参考源码提交；不改平台测试、不激活数据或改valid()','sources':{p:sha(p) for p in ['judge.py','data/openjudge/catalog.json','data/openjudge/limits.json','collab/gmyhf-pending-triage.json']},'selfchecks':m.selfcheck()}
 session=oj_submit.Session().login();anonymous=oj_submit.Session()
 for n in m.NUMBERS:
