  e=entries[n];records=e['read_only_comparison']['records'];base=Path('data/openjudge/tests/admin_download')/str(n);ref=Path(e['made_reference']);validator=ref.with_name('producecase.py');page=Path(f'data/openjudge/pages/practice__{n}.html');row=next((r for r in result['entries'] if r['global_number']==n),None)
  if row is None:row={'global_number':n,'title':e['title'],'reference':str(ref),'reference_sha256':sha(ref),'validator':str(validator),'validator_sha256':sha(validator),'page':str(page),'page_sha256':sha(page),'checks':{}};result['entries'].append(row)
